INSERT INTO `programs` (`id`, `category_id`, `title`, `slug`, `summary`, `description`, `duration_hours`, `duration_days`, `level`, `image`, `is_featured`, `is_active`, `created_at`, `updated_at`) VALUES ('1', '6', 'أفضل ممارسات التميز القيادي والأداء الإبداعي', 'program-001', NULL, 'يقدم برنامج «أفضل ممارسات التميز القيادي والأداء الإبداعي» تجربة تدريبية تطبيقية تساعد المشاركين على تحويل المفاهيم إلى ممارسات قابلة للاستخدام في العمل. يركز المحتوى على المهارات القيادية والإدارية، التواصل واتخاذ القرار، إدارة الفرق، وتطبيق أدوات عملية لتحسين الأداء. ويتضمن تمارين وحالات عملية ونقاشات موجهة تساعد على بناء خطة تطبيق بعد البرنامج، مع مراعاة اختلاف الخبرات واحتياجات الجهات الحكومية والخاصة وغير الربحية.', '15', '3', 'متوسط', 'assets/images/programs/courses/course-001.jpeg', '1', '1', '2026-08-09 14:43:31', '2026-08-09 14:43:31');
INSERT INTO `programs` (`id`, `category_id`, `title`, `slug`, `summary`, `description`, `duration_hours`, `duration_days`, `level`, `image`, `is_featured`, `is_active`, `created_at`, `updated_at`) VALUES ('2', '6', 'المهارات الديناميكية في إدارة الصراعات ومعالجة المواقف الصعبة', 'program-002', NULL, 'يقدم برنامج «المهارات الديناميكية في إدارة الصراعات ومعالجة المواقف الصعبة» تجربة تدريبية تطبيقية تساعد المشاركين على تحويل المفاهيم إلى ممارسات قابلة للاستخدام في العمل. يركز المحتوى على تشخيص مصادر الخلاف، اختيار أسلوب التدخل المناسب، إدارة الحوار تحت الضغط، وتحويل المواقف الصعبة إلى اتفاقات عملية. ويتضمن تمارين وحالات عملية ونقاشات موجهة تساعد على بناء خطة تطبيق بعد البرنامج، مع مراعاة اختلاف الخبرات واحتياجات الجهات الحكومية والخاصة وغير الربحية.', '15', '3', 'متقدم', 'assets/images/programs/courses/course-002.jpeg', '0', '1', '2026-08-09 14:43:31', '2026-08-09 14:43:31');
