INSERT INTO `programs` (`id`, `category_id`, `title`, `slug`, `summary`, `description`, `duration_hours`, `duration_days`, `level`, `image`, `is_featured`, `is_active`, `created_at`, `updated_at`) VALUES ('46', '3', 'مهارات أعمال المحاسبة العملية', 'program-046', NULL, 'يقدم برنامج «مهارات أعمال المحاسبة العملية» تجربة تدريبية تطبيقية تساعد المشاركين على تحويل المفاهيم إلى ممارسات قابلة للاستخدام في العمل. يركز المحتوى على الدورة المحاسبية، معالجة العمليات اليومية، التسويات، قراءة القوائم الأساسية، وتحسين الدقة والرقابة على البيانات المالية. ويتضمن تمارين وحالات عملية ونقاشات موجهة تساعد على بناء خطة تطبيق بعد البرنامج، مع مراعاة اختلاف الخبرات واحتياجات الجهات الحكومية والخاصة وغير الربحية.', '15', '3', 'متوسط', 'assets/images/programs/courses/course-046.jpeg', '0', '1', '2026-08-09 14:43:31', '2026-08-09 14:43:31');
