INSERT INTO `success_stories` (`id`, `title`, `client_name`, `position_or_company`, `quote_or_description`, `stat_number`, `stat_label`, `image`, `sort_order`, `is_active`, `created_at`, `updated_at`) VALUES ('3', 'الجودة والتميز المؤسسي', 'برامج مؤسسية', NULL, 'برامج تطبيقية في نظم الجودة والتميز وقياس الأداء والتحسين المستمر للعمليات.', NULL, NULL, 'assets/images/success/success-quality-final.jpg', '3', '1', '2026-08-09 11:30:28', '2026-08-09 11:30:28');
